/*  Matrix operations – sum, difference and product.
    The program reads two square matrices from files whose names are
    supplied as command‑line arguments and prints the three resulting
    matrices to stdout in the required format. */

#include <stdio.h>
#include <stdlib.h>

/* Read a matrix from file.
   Parameters:
     filename – name of the file,
     rows, cols – pointers where the dimensions will be stored.
   Returns: pointer to a dynamically allocated array containing
            the matrix elements in row‑major order.
*/
static int *read_matrix(const char *filename, int *rows, int *cols)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening file %s\n", filename);
        exit(EXIT_FAILURE);
    }

    if (fscanf(fp, "%d %d", rows, cols) != 2) {
        fprintf(stderr, "Invalid header in %s\n", filename);
        fclose(fp);
        exit(EXIT_FAILURE);
    }

    int n = (*rows) * (*cols);
    int *mat = malloc(n * sizeof(int));
    if (!mat) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(fp);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < n; ++i) {
        if (fscanf(fp, "%d", &mat[i]) != 1) {
            fprintf(stderr, "Not enough elements in %s\n", filename);
            free(mat);
            fclose(fp);
            exit(EXIT_FAILURE);
        }
    }

    fclose(fp);
    return mat;
}

/* Print a matrix to stdout.
   Parameters:
     mat – pointer to the data,
     rows, cols – dimensions of the matrix. */
static void print_matrix(const int *mat, int rows, int cols)
{
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (j > 0) putchar(' ');
            printf("%d", mat[i * cols + j]);
        }
        putchar('\n');
    }
}

/* Compute sum of two matrices: res = A + B. */
static void add_matrix(const int *A, const int *B, int *res,
                       int rows, int cols)
{
    int n = rows * cols;
    for (int i = 0; i < n; ++i) {
        res[i] = A[i] + B[i];
    }
}

/* Compute difference of two matrices: res = A - B. */
static void sub_matrix(const int *A, const int *B, int *res,
                       int rows, int cols)
{
    int n = rows * cols;
    for (int i = 0; i < n; ++i) {
        res[i] = A[i] - B[i];
    }
}

/* Compute product of two matrices: res = A * B. */
static void mul_matrix(const int *A, const int *B, int *res,
                       int rows, int cols)
{
    /* Since the matrices are square, rows == cols. */
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            long long sum = 0;          // use long long to avoid overflow
            for (int k = 0; k < cols; ++k)
                sum += (long long)A[i * cols + k] *
                       (long long)B[k * cols + j];
            res[i * cols + j] = (int)sum;
        }
    }
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr,
                "Usage: %s <matrix_file_A> <matrix_file_B>\n",
                argv[0]);
        return EXIT_FAILURE;
    }

    int rowsA, colsA, rowsB, colsB;

    /* Read matrices from files. */
    int *A = read_matrix(argv[1], &rowsA, &colsA);
    int *B = read_matrix(argv[2], &rowsB, &colsB);

    /* Verify that both are square and of the same size. */
    if (rowsA != colsA || rowsB != colsB ||
        rowsA != rowsB || colsA != colsB) {
        fprintf(stderr,
                "Matrices must be square and of equal dimensions\n");
        free(A);
        free(B);
        return EXIT_FAILURE;
    }

    int n = rowsA * colsA;

    /* Allocate memory for results. */
    int *sum  = malloc(n * sizeof(int));
    int *diff = malloc(n * sizeof(int));
    int *prod = malloc(n * sizeof(int));

    if (!sum || !diff || !prod) {
        fprintf(stderr, "Memory allocation failed\n");
        free(A); free(B);
        free(sum); free(diff); free(prod);
        return EXIT_FAILURE;
    }

    /* Compute operations. */
    add_matrix(A, B, sum, rowsA, colsA);
    sub_matrix(A, B, diff, rowsA, colsA);
    mul_matrix(A, B, prod, rowsA, colsA);

    /* Output results. */
    print_matrix(sum,  rowsA, colsA); putchar('\n');
    print_matrix(diff, rowsA, colsA); putchar('\n');
    print_matrix(prod, rowsA, colsA);

    /* Free allocated memory. */
    free(A);
    free(B);
    free(sum);
    free(diff);
    free(prod);

    return EXIT_SUCCESS;
}

