    }

    long long trace = 0;          // use long long to avoid overflow
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int val;
            if (scanf("%d", &val) != 1) {
                fprintf(stderr, "Not enough matrix elements.\n");
                return EXIT_FAILURE;
