#include <stdio.h>
#include <math.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;   // error reading n

    double Y = 0.0;

    for (int i = 0; i < n; ++i) {
        double Z, B, A, beta;
        if (scanf("%lf %lf %lf %lf", &Z, &B, &A, &beta) != 4)
            return 1;   // error reading a set

        double tan_beta = tan(beta);
        /* Avoid division by zero – if tan(beta)==0 the term is undefined.
           In such case we skip or handle as needed. Here we simply continue. */
        if (tan_beta == 0.0) {
            fprintf(stderr, "Warning: tan(beta) is zero for set %d.\n", i + 1);
            continue;
        }

        double term = Z * Z * Z - B + (A * A) / (tan_beta * tan_beta);
        Y += term;
    }

    printf("%.6f\n", Y);
    return 0;
}

