/* Integer exponentiation: base^exp (exp >= 0) */
static uint64_t int_pow(uint64_t base, unsigned int exp)
{
    uint64_t result = 1;
    while (exp > 0) {
        if (exp & 1)
            result *= base;
        base *= base;
        exp >>= 1;
    }
    return result;
}

int main(void)
{
    long long N;          /* upper limit of the sum */
    unsigned int k;       /* exponent, non‑negative */

    /* Read two integers from standard input */
    if (scanf("%lld %u", &N, &k) != 2) {
        fprintf(stderr, "Error: invalid input.\n");
        return 1;
    }

    /* Compute the sum 1^k + 2^k + ... + N^k */
    uint64_t sum = 0;
    for (long long i = 1; i <= N; ++i) {
        sum += int_pow((uint64_t)i, k);
    }

    printf("%llu\n", sum);
    return 0;
}

