/* Возводим число в целую степень без использования pow */
double int_pow(double base, int exp)
{
    double result = 1.0;
    for (int i = 0; i < exp; ++i) {
        result *= base;
    }
    return result;
}

int main(void)
{
    /* диапазон x от -1.1 до 0.3 с шагом 0.2 */
    double x_start = -1.1;
    double x_end   =  0.3;
    double step    =  0.2;

    for (double x = x_start; x <= x_end + 1e-9; x += step) {
        for (int m = 1; m <= 5; ++m) {
            /* x^m */
            double xm = int_pow(x, m);

            /* sin(x*m)^m */
            double sin_val = sin(x * m);
            double sin_m   = int_pow(sin_val, m);

            double z = xm * sin_m;

            printf("%.1f %d %.6f\n", x, m, z);
        }
    }

    return 0;
}

