int main(void) {
    double x, y;

    /* Считываем два действительных числа (углы в радианах) */
    if (scanf("%lf %lf", &x, &y) != 2) {
        return 1;   // ошибка ввода
    }

    /* Вычисляем выражение: (1 - tan(x))^(cot(x)) + cos(x - y) */
    double tan_x = tan(x);
    double cot_x = 1.0 / tan_x;          // cot x = 1/tan x
    double part1 = pow(1.0 - tan_x, cot_x);
    double part2 = cos(x - y);

    double result = part1 + part2;

    /* Выводим результат с шестью знаками после запятой */
    printf("%.6f\n", result);

    return 0;
}

