    long long a, mu, m, x0;
    int n;
    if (scanf("%lld %lld %lld %lld %d", &a, &mu, &m, &x0, &n) != 5)
        return 1;

    /* Current state of the generator */
    long long xi = x0;

    for (int i = 0; i < n; ++i) {
        /* Output current value y(i) = x(i)/m with 6 decimals */
        double yi = (double)xi / (double)m;
        printf("%.6f\n", yi);

        /* Compute next state: x(i+1) = (a * xi + mu) mod m */
        long long prod = a * xi + mu;          // may overflow 64‑bit, but
                                               // problem statement assumes it fits
        xi = prod % m;
    }

    return 0;
}

