int main(void)
{
    int a, b;          // размеры отверстия
    int x, y, z;       // габариты кирпича

    /* читаем входные данные */
    if (scanf("%d %d", &a, &b) != 2) return 1;
    if (scanf("%d %d %d", &x, &y, &z) != 3) return 1;

    /* сортируем размеры кирпича по возрастанию */
    int dims[3] = {x, y, z};
    for (int i = 0; i < 2; ++i)
        for (int j = i + 1; j < 3; ++j)
            if (dims[i] > dims[j]) {
                int tmp = dims[i];
                dims[i] = dims[j];
                dims[j] = tmp;
            }

    /* проверяем, можно ли поместить две меньшие стороны в отверстие */
    int ok = 0;
    if ((dims[0] <= a && dims[1] <= b) ||
        (dims[0] <= b && dims[1] <= a))
        ok = 1;

    printf("%s\n", ok ? "yes" : "no");
    return 0;
}

