int main(void)
{
    double a, b, h;
    if (scanf("%lf %lf %lf", &a, &b, &h) != 3) {
        return 1;          /* input error */
    }

    for (double x = a; x <= b + 1e-12; x += h) {   /* +eps to include b if it falls on step */
        double ln_x = log(x);                      /* natural logarithm of x */
        double sin_ln = sin(ln_x);
        double cos_ln = cos(ln_x);

        /* avoid division by zero – if sin is very close to 0, set f to a large value */
        double f;
        if (fabs(sin_ln) < 1e-12)
            f = INFINITY;          /* or some sentinel value */
        else
            f = pow(cos_ln / sin_ln, 2.0);

        printf("%.2f %.6f\n", x, f);
    }

    return 0;
}

