#include <stdio.h>
#include <math.h>

int main(void) {
    double a, b, c, d, k;
    if (scanf("%lf %lf %lf %lf %lf", &a, &b, &c, &d, &k) != 5)
        return 1;   // input error

    /* Coefficients of the quadratic equation */
    double A = a;
    double B = b - d;
    double C = c - k;

    if (fabs(A) < 1e-12) {          // Degenerate to linear or constant
        if (fabs(B) < 1e-12) {
            /* Equation reduces to C = 0 */
            if (fabs(C) < 1e-12)
                printf("no roots\n");   // All real numbers satisfy, but per problem treat as no roots
            else
                printf("no roots\n");
        } else {
            double root = -C / B;
            printf("%.6f\n", root);
        }
        return 0;
    }

    double D = B * B - 4.0 * A * C;

    if (D > 1e-12) {                // Two distinct real roots
        double sqrtD = sqrt(D);
        double x1 = (-B - sqrtD) / (2.0 * A);
        double x2 = (-B + sqrtD) / (2.0 * A);
        if (x1 > x2) {
            double tmp = x1;
            x1 = x2;
            x2 = tmp;
        }
        printf("%.6f %.6f\n", x1, x2);
    } else if (fabs(D) <= 1e-12) {   // One real root
        double x = -B / (2.0 * A);
        printf("%.6f\n", x);
    } else {                         // No real roots
        printf("no roots\n");
    }

    return 0;
}

#include <stdio.h>
#include <ctype.h>

int main(void) {
    char buf[1024];

    /* Read one line of input */
    if (!fgets(buf, sizeof(buf), stdin))
        return 0;   /* no input */

    /* Remove trailing newline if present */
    for (char *p = buf; *p != '\0'; ++p)
        if (*p == '\n') {
            *p = '\0';
            break;
        }

    char *s = buf;

    /* Optional leading sign */
    if (*s == '+' || *s == '-')
        s++;

    /* Must have at least one digit and only digits thereafter */
    if (!isdigit((unsigned char)*s)) {
        printf("no\n");
        return 0;
    }

    while (*s) {
        if (!isdigit((unsigned char)*s)) {
            printf("no\n");
            return 0;
        }
        s++;
    }

    printf("yes\n");
    return 0;
}

