int main(void) {
    int n;

    /* Считываем одно пятизначное число */
    if (scanf("%d", &n) != 1)
        return 1;   // ошибка чтения

    /* Извлекаем цифры числа */
    int a = n / 10000;          // первая
    int b = (n / 1000) % 10;    // вторая
    int c = (n / 100) % 10;     // третья
    int d = (n / 10) % 10;      // четвертая
