#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 1;

    /* Allocate the matrix */
    int **a = malloc(n * sizeof(int*));
    for (int i = 0; i < n; ++i)
        a[i] = calloc(n, sizeof(int));

    int val = 1;
    /* Fill by diagonals */
    for (int sum = 0; sum <= 2*(n-1); ++sum) {
        if (sum % 2 == 0) {          /* top‑to‑bottom on this diagonal   */
            int i_start = (sum < n) ? 0 : sum - (n-1);
            int j_start = sum - i_start;
            for (int k = 0; k <= sum && i_start + k < n && j_start - k >= 0; ++k) {
                a[i_start + k][j_start - k] = val++;
            }
        } else {                     /* bottom‑to‑top on this diagonal   */
            int i_start = (sum < n) ? sum : n-1;
            int j_start = sum - i_start;
            for (int k = 0; k <= sum && i_start - k >= 0 && j_start + k < n; ++k) {
                a[i_start - k][j_start + k] = val++;
            }
        }
    }

    /* Output the matrix */
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j)
            printf("%4d", a[i][j]);
        putchar('\n');
    }

    /* Free memory */
    for (int i = 0; i < n; ++i) free(a[i]);
    free(a);
    return 0;
}

