#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 1;

    double **a = malloc(n * sizeof(double*));
    for (int i = 0; i < n; ++i)
        a[i] = malloc(n * sizeof(double));

    /* read matrix */
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            scanf("%lf", &a[i][j]);

    /* find position of element with maximum absolute value */
    int max_i = 0, max_j = 0;
    double max_abs = fabs(a[0][0]);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            double val = fabs(a[i][j]);
            if (val > max_abs) {
                max_abs = val;
                max_i = i;
                max_j = j;
            }
        }
    }

    /* swap row with last row */
    if (max_i != n-1) {
        double *tmp = a[max_i];
        a[max_i] = a[n-1];
        a[n-1] = tmp;
    }

    /* after swapping rows, the element might have moved to another column index,
       but we still need to swap its column with last column. */
    if (max_j != n-1) {
        for (int i = 0; i < n; ++i) {
            double temp = a[i][max_j];
            a[i][max_j] = a[i][n-1];
            a[i][n-1] = temp;
        }
    }

    /* output matrix */
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            printf("%.6g", a[i][j]);
            if (j + 1 < n) putchar(' ');
        }
        putchar('\n');
    }

    /* free memory */
    for (int i = 0; i < n; ++i)
        free(a[i]);
    free(a);

    return 0;
}

