#include <stdlib.h>

#define N 7

/* Сортировка простым пузырьком для диапазона [l..r] */
static void sort_sub(int *col, int l, int r)
{
    if (l >= r) return;
    for (int i = l; i <= r; ++i) {
        for (int j = l; j < r; ++j) {
            if (col[j] > col[j + 1]) {
                int tmp = col[j];
                col[j] = col[j + 1];
                col[j + 1] = tmp;
            }
        }
    }
}

int main(void)
{
    int a[N][N];

    /* Ввод матрицы */
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (scanf("%d", &a[i][j]) != 1) {
                fprintf(stderr, "Ошибка ввода\n");
                return EXIT_FAILURE;
            }
        }
    }

    /* Обрабатываем каждый столбец */
    for (int col = 0; col < N; ++col) {
        int min_val = a[0][col];
        int max_val = a[0][col];
        int min_idx = 0, max_idx = 0;

        /* Находим индексы минимального и максимального элементов */
        for (int row = 1; row < N; ++row) {
            if (a[row][col] < min_val) {
                min_val = a[row][col];
                min_idx = row;
            }
            if (a[row][col] > max_val) {
                max_val = a[row][col];
                max_idx = row;
            }
        }

        /* Сортируем элементы между ними, если они есть */
        int l = min(min_idx, max_idx);
        int r = max(max_idx, min_idx);
        if (r - l > 1) {          /* есть хотя бы один элемент в диапазоне */
            sort_sub(&a[0][col], l + 1, r - 1);
        }
    }

    /* Выводим полученную матрицу */
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            printf("%4d", a[i][j]);
        }
        putchar('\n');
    }

    return EXIT_SUCCESS;
}

