int main(void) {
    double x;
    if (scanf("%lf", &x) != 1)
        return 1;          // no input

    /* Special case: cube root of zero is zero */
    if (fabs(x) < 1e-12) {
        printf("0.000000\n");
        return 0;
    }

    double y = x;                 // initial guess
    double next_y, diff;

    do {
        /* Compute the next approximation using the given formula */
        double denom = 2 * y * y + x / y;
        if (fabs(denom) < 1e-15) {   // avoid division by zero
            break;
        }
        next_y = 0.5 * (y + 3 * x / denom);
        diff = fabs(next_y - y);
        y = next_y;
    } while (diff >= 1e-5);

    printf("%.6f\n", y);
    return 0;
}

