int is_composite(int n) {
    if (n <= 1)
        return 0;                 // numbers ≤ 1 are not composite

    int limit = (int)sqrt((double)n);
    for (int i = 2; i <= limit; ++i) {
        if (n % i == 0)
            return 1;             // found a divisor → composite
    }
    return 0;                     // no divisors found → not composite
}

