int main(void) {
    int op;
    if (scanf("%d", &op) != 1) return 0;

    const int DAY = 24 * 60 * 60;   // количество секунд в сутках

    if (op == 1) {                 /* вычитание delta из времени */
        int h, m, s, delta;
        if (scanf("%d %d %d %d", &h, &m, &s, &delta) != 4) return 0;

        int total = h * 3600 + m * 60 + s;          // текущее время в секундах
        int res   = (total - delta) % DAY;          // вычитаем и берём остаток по модулю дня
        if (res < 0) res += DAY;                    // корректируем отрицательный остаток

        int rh = res / 3600;
        int rm = (res % 3600) / 60;
        int rs = res % 60;

        printf("%d %d %d\n", rh, rm, rs);
    } else if (op == 2) {           /* разность между двумя моментами времени */
        int h1, m1, s1, h2, m2, s2;
        if (scanf("%d %d %d %d %d %d", &h1, &m1, &s1,
                  &h2, &m2, &s2) != 6) return 0;

        int t1 = h1 * 3600 + m1 * 60 + s1;
        int t2 = h2 * 3600 + m2 * 60 + s2;

        long diff = (long)t1 - (long)t2;           // разность может быть отрицательной
        if (diff < 0) diff = -diff;                // берём абсолютную величину

        printf("%ld\n", diff);
    }

    return 0;
}

