#include <stdio.h>
#include <stdlib.h>

/* Function to compute the characteristic of a column */
static int column_characteristic(int **mat, int n, int col)
{
    int sum = 0;
    for (int i = 0; i < n; ++i) {
        int val = mat[i][col];
        if (val < 0 && (abs(val) % 2 == 1)) {   /* negative odd element */
            sum += abs(val);
        }
    }
    return sum;
}

/* Comparison function for qsort: ascending by characteristic,
   ties are broken by original column index to keep stability. */
static int compare_columns(const void *a, const void *b)
{
    const struct {
        int idx;
        int charac;
    } *colA = a, *colB = b;

    if (colA->charac != colB->charac)
        return colA->charac - colB->charac;
    return colA->idx - colB->idx;   /* stable tie‑break */
}

