    }

    /* Allocate matrix */
    int **mat = malloc(n * sizeof(int *));
    for (int i = 0; i < n; ++i)
        mat[i] = malloc(m * sizeof(int));

    /* Read matrix */
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            if (scanf("%d", &mat[i][j]) != 1) {
                fprintf(stderr, "Failed to read element.\n");
                return EXIT_FAILURE;
            }

    /* Compute characteristics and prepare index array */
    struct {
        int idx;
        int charac;
    } *cols = malloc(m * sizeof(*cols));
    for (int j = 0; j < m; ++j) {
        cols[j].idx = j;
        cols[j].charac = column_characteristic(mat, n, j);
    }

    /* Sort columns by characteristic */
    qsort(cols, m, sizeof(*cols), compare_columns);

    /* Output reordered matrix */
    for (int i = 0; i < n; ++i) {
        for (int k = 0; k < m; ++k) {
            if (k > 0) putchar(' ');
            printf("%d", mat[i][cols[k].idx]);
        }
        putchar('\n');
    }

    /* Free memory */
    for (int i = 0; i < n; ++i)
        free(mat[i]);
    free(mat);
    free(cols);

    return EXIT_SUCCESS;
}

