#include <stdio.h>
#include <stdlib.h>

/* Selection sort – counts comparisons */
void selection_sort(int *a, int n, long long *cmp)
{
    *cmp = 0;
    for (int i = 0; i < n - 1; ++i) {
        int min_idx = i;
        for (int j = i + 1; j < n; ++j) {
            (*cmp)++;
            if (a[j] < a[min_idx]) {
                min_idx = j;
            }
        }
        /* swap */
        int tmp = a[i];
        a[i] = a[min_idx];
        a[min_idx] = tmp;
    }
}

/* Shaker sort – counts comparisons */
void shaker_sort(int *a, int n, long long *cmp)
{
    *cmp = 0;
    int left = 0, right = n - 1;
    while (left < right) {
        /* forward pass */
        for (int i = left; i < right; ++i) {
            (*cmp)++;
            if (a[i] > a[i + 1]) {
                int tmp = a[i];
                a[i] = a[i + 1];
                a[i + 1] = tmp;
            }
        }
        --right;

        /* backward pass */
        for (int i = right; i > left; --i) {
            (*cmp)++;
            if (a[i - 1] > a[i]) {
                int tmp = a[i];
                a[i] = a[i - 1];
                a[i - 1] = tmp;
            }
        }
        ++left;
    }
}

