#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1 || N <= 0) return 1;

    /* Allocate matrix */
    double **a = malloc(N * sizeof(double*));
    for (int i = 0; i < N; ++i)
        a[i] = malloc(N * sizeof(double));

    /* Read matrix */
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int val;
            if (scanf("%d", &val) != 1) return 1;
            a[i][j] = (double)val;
        }
    }

    /* Gaussian elimination with partial pivoting */
    double det = 1.0;
    int sign = 1;          // +1 or -1 depending on number of row swaps

    for (int k = 0; k < N; ++k) {
        /* Find pivot */
        int piv_row = k;
        double max_val = fabs(a[k][k]);
        for (int i = k + 1; i < N; ++i) {
            if (fabs(a[i][k]) > max_val) {
                max_val = fabs(a[i][k]);
                piv_row = i;
            }
        }

        /* If pivot is zero, determinant is zero */
        if (max_val == 0.0) {
            det = 0.0;
            break;
        }

        /* Swap rows if needed */
        if (piv_row != k) {
            double *tmp = a[k];
            a[k] = a[piv_row];
            a[piv_row] = tmp;
            sign *= -1;
        }

        det *= a[k][k];

        /* Eliminate below */
        for (int i = k + 1; i < N; ++i) {
            double factor = a[i][k] / a[k][k];
            for (int j = k; j < N; ++j)
                a[i][j] -= factor * a[k][j];
        }
    }

    det *= sign;

    /* Output as integer if it is close to an integer */
    long long int_det = llround(det);
    if (fabs(det - int_det) < 1e-6)
        printf("%lld\n", int_det);
    else
        printf("%.10f\n", det);

    /* Free memory */
    for (int i = 0; i < N; ++i) free(a[i]);
    free(a);

    return 0;
}

