    if (m > 0 && m <= 32) {
        uint32_t mask_m;
        if (m == 32)
            mask_m = ~0u;          /* все биты */
        else
            mask_m = (1u << m) - 1;

        /* старшие m бит y: берём верхние m бит и сдвигаем вниз */
        uint32_t high_y_bits;
        if (m == 32)
